/*!
 * sqlite.js - Simplified SQLite Database
 * Standard SQLite without complexity
 */

const Database = require('better-sqlite3');
const fs = require('fs');
const path = require('path');
const { v4: uuidv4 } = require('uuid');

class SQLiteDB {
  constructor(dbPath = './data/mutech.db') {
    this.dbPath = dbPath;

    // Ensure data directory exists
    const dbDir = path.dirname(dbPath);
    if (!fs.existsSync(dbDir)) {
      fs.mkdirSync(dbDir, { recursive: true });
    }

    this.db = new Database(dbPath);

    this.initSchema();
    this.prepareStatements();

    console.log(`SQLite database initialized: ${dbPath}`);
  }

  initSchema() {
    const schema = `
      CREATE TABLE IF NOT EXISTS exhibits (
        id TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
      );

      CREATE TABLE IF NOT EXISTS works (
        id TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        parent_id TEXT REFERENCES exhibits(id),
        fast_trigger BOOLEAN DEFAULT FALSE,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
      );

      CREATE TABLE IF NOT EXISTS units (
        id TEXT PRIMARY KEY,
        parent_id TEXT REFERENCES works(id),
        host TEXT NOT NULL,
        hostname TEXT,
        ip TEXT,
        unit_type TEXT NOT NULL,
        automation BOOLEAN DEFAULT TRUE,
        active BOOLEAN DEFAULT TRUE,
        args TEXT,
        state INTEGER DEFAULT -1,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
      );

      CREATE INDEX IF NOT EXISTS idx_works_parent ON works(parent_id);
      CREATE INDEX IF NOT EXISTS idx_units_parent ON units(parent_id);
      CREATE INDEX IF NOT EXISTS idx_units_active ON units(active);
      CREATE INDEX IF NOT EXISTS idx_units_automation ON units(automation);
    `;

    this.db.exec(schema);
  }

  prepareStatements() {
    this.stmt = {
      // READ operations
      getAllExhibits: this.db.prepare('SELECT * FROM exhibits ORDER BY name'),
      getAllWorks: this.db.prepare('SELECT * FROM works ORDER BY name'),
      getAllUnits: this.db.prepare('SELECT * FROM units ORDER BY host'),
      getWorkById: this.db.prepare('SELECT * FROM works WHERE id = ?'),
      getWorksByParent: this.db.prepare('SELECT * FROM works WHERE parent_id = ? ORDER BY name'),
      getUnitsByParent: this.db.prepare('SELECT * FROM units WHERE parent_id = ? ORDER BY host'),
      getAutomationUnits: this.db.prepare('SELECT * FROM units WHERE automation = TRUE AND active = TRUE ORDER BY host'),

      // WRITE operations
      insertExhibit: this.db.prepare('INSERT INTO exhibits (id, name) VALUES (?, ?)'),
      insertWork: this.db.prepare('INSERT INTO works (id, name, parent_id, fast_trigger) VALUES (?, ?, ?, ?)'),
      insertUnit: this.db.prepare('INSERT INTO units (id, parent_id, host, hostname, ip, unit_type, automation, active, args, state) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)'),

      updateExhibit: this.db.prepare('UPDATE exhibits SET name = ? WHERE id = ?'),
      updateWork: this.db.prepare('UPDATE works SET name = ?, parent_id = ?, fast_trigger = ? WHERE id = ?'),
      updateUnit: this.db.prepare('UPDATE units SET parent_id = ?, host = ?, hostname = ?, ip = ?, unit_type = ?, automation = ?, active = ?, args = ?, state = ? WHERE id = ?'),
      updateUnitState: this.db.prepare('UPDATE units SET state = ? WHERE id = ?'),

      deleteExhibit: this.db.prepare('DELETE FROM exhibits WHERE id = ?'),
      deleteWork: this.db.prepare('DELETE FROM works WHERE id = ?'),
      deleteUnit: this.db.prepare('DELETE FROM units WHERE id = ?'),
      deleteWorksByParent: this.db.prepare('DELETE FROM works WHERE parent_id = ?'),
      deleteUnitsByParent: this.db.prepare('DELETE FROM units WHERE parent_id = ?')
    };
  }

  // READ operations - return camelCase objects
  getExhibits() {
    return this.stmt.getAllExhibits.all().map(this.parseExhibit);
  }

  getWorks() {
    return this.stmt.getAllWorks.all().map(this.parseWork);
  }

  getUnits() {
    return this.stmt.getAllUnits.all().map(this.parseUnit);
  }

  getWorkById(id) {
    const work = this.stmt.getWorkById.get(id);
    return work ? this.parseWork(work) : null;
  }

  getWorksByExhibit(exhibitId) {
    return this.stmt.getWorksByParent.all(exhibitId).map(this.parseWork);
  }

  getUnitsByWork(workId) {
    return this.stmt.getUnitsByParent.all(workId).map(this.parseUnit);
  }

  getAutomationUnits() {
    return this.stmt.getAutomationUnits.all().map(this.parseUnit);
  }

  addExhibit(exhibit) {
    if (!exhibit.id) {
      exhibit.id = uuidv4();
    }

    this.stmt.insertExhibit.run(exhibit.id, exhibit.name);
    return exhibit;
  }

  addWork(work) {
    if (!work.id) {
      work.id = uuidv4();
    }

    this.stmt.insertWork.run(
      work.id,
      work.name,
      work.parentId || null,
      work.fastTrigger ? 1 : 0
    );
    return work;
  }

  addUnit(unit) {
    if (!unit.id) {
      unit.id = uuidv4();
    }

    this.stmt.insertUnit.run(
      unit.id,
      unit.parentId || null,
      unit.host,
      unit.hostname || null,
      unit.ip || null,
      unit.unitType,
      unit.automation ? 1 : 0,
      unit.active !== false ? 1 : 0,
      JSON.stringify(unit.args || {}),
      unit.state || -1
    );
    return unit;
  }

  updateExhibit(id, exhibit) {
    this.stmt.updateExhibit.run(exhibit.name, id);
    return exhibit;
  }

  updateWork(id, work) {
    this.stmt.updateWork.run(
      work.name,
      work.parentId,
      work.fastTrigger || false,
      id
    );
    return work;
  }

  updateUnit(id, unit) {
    this.stmt.updateUnit.run(
      unit.parentId,
      unit.host,
      unit.hostname || null,
      unit.ip || null,
      unit.unitType,
      unit.automation !== false,
      unit.active !== false,
      JSON.stringify(unit.args || {}),
      unit.state || -1,
      id
    );
    return unit;
  }

  updateUnitState(id, state) {
    this.stmt.updateUnitState.run(state, id);
  }

  deleteExhibit(id) {
    // Cascade delete: exhibit -> works -> units
    const works = this.stmt.getWorksByParent.all(id);
    works.forEach(work => {
      this.stmt.deleteUnitsByParent.run(work.id);
    });
    this.stmt.deleteWorksByParent.run(id);
    this.stmt.deleteExhibit.run(id);
  }

  deleteWork(id) {
    // Cascade delete: work -> units
    this.stmt.deleteUnitsByParent.run(id);
    this.stmt.deleteWork.run(id);
  }

  deleteUnit(id) {
    this.stmt.deleteUnit.run(id);
  }

  // Field conversion: snake_case -> camelCase
  parseExhibit(exhibit) {
    return {
      ...exhibit,
      createdAt: exhibit.created_at
    };
  }

  parseWork(work) {
    return {
      ...work,
      parentId: work.parent_id,
      fastTrigger: work.fast_trigger,
      createdAt: work.created_at
    };
  }

  parseUnit(unit) {
    return {
      ...unit,
      parentId: unit.parent_id,
      unitType: unit.unit_type,
      args: unit.args ? JSON.parse(unit.args) : {},
      createdAt: unit.created_at
    };
  }

  close() {
    this.db.close();
  }
}

module.exports = SQLiteDB;

