     1→/*!
     2→ * migration.js - Migrate from LowDB (db.json) to SQLite
     3→ * Run this once to migrate existing data
     4→ */
     5→
     6→const fs = require('fs');
     7→const path = require('path');
     8→const SQLiteDB = require('./sqlite');
     9→const { v4: uuidv4 } = require('uuid');
    10→
    11→class DatabaseMigration {
    12→  constructor(jsonPath = './db.json', sqlitePath = './data/mutech.db') {
    13→    this.jsonPath = jsonPath;
    14→    this.sqlitePath = sqlitePath;
    15→  }
    16→
    17→  async migrate() {
    18→    console.log('Starting database migration from LowDB to SQLite...');
    19→    
    20→    // Read existing JSON data
    21→    if (!fs.existsSync(this.jsonPath)) {
    22→      console.log('No existing db.json found. Creating fresh SQLite database...');
    23→      const db = new SQLiteDB(this.sqlitePath);
    24→      db.close();
    25→      return;
    26→    }
    27→
    28→    let jsonData;
    29→    try {
    30→      const jsonContent = fs.readFileSync(this.jsonPath, 'utf8');
    31→      jsonData = JSON.parse(jsonContent);
    32→      console.log('Successfully read existing db.json');
    33→    } catch (error) {
    34→      console.error('Error reading db.json:', error);
    35→      throw error;
    36→    }
    37→
    38→    // Initialize SQLite database
    39→    const db = new SQLiteDB(this.sqlitePath);
    40→
    41→    try {
    42→      // Backup existing SQLite if it exists
    43→      if (fs.existsSync(this.sqlitePath)) {
    44→        const backupPath = `${this.sqlitePath}.backup.${Date.now()}`;
    45→        fs.copyFileSync(this.sqlitePath, backupPath);
    46→        console.log(`Backed up existing SQLite to: ${backupPath}`);
    47→      }
    48→
    49→      // Migrate data in transaction
    50→      const migrateTransaction = db.db.transaction(() => {
    51→        // Migrate exhibits
    52→        if (jsonData.exhibits && Array.isArray(jsonData.exhibits)) {
    53→          console.log(`Migrating ${jsonData.exhibits.length} exhibits...`);
    54→          jsonData.exhibits.forEach(exhibit => {
    55→            if (!exhibit.id) exhibit.id = uuidv4();
    56→            const name = exhibit.name || 'Unnamed Exhibit';
    57→            db.stmt.insertExhibit.run(exhibit.id, name);
    58→          });
    59→        }
    60→
    61→        // Migrate works
    62→        if (jsonData.works && Array.isArray(jsonData.works)) {
    63→          console.log(`Migrating ${jsonData.works.length} works...`);
    64→          jsonData.works.forEach((work, index) => {
    65→            try {
    66→              if (!work.id) work.id = uuidv4();
    67→              
    68→              // Convert parentId to parent_id for consistency and ensure it's not undefined
    69→              const parentId = work.parentId || work.parent_id || null;
    70→              const name = work.name || 'Unnamed Work';
    71→              const fastTrigger = 0; // fast_trigger defaults to 0 (false as integer)
    72→              
    73→              console.log(`Migrating work: ${name} (ID: ${work.id}, Parent ID: ${parentId})`);
    74→              
    75→              // Debug the exact values we're trying to insert
    76→              console.log(`Values: id="${work.id}", name="${name}", parentId="${parentId}", fastTrigger=${fastTrigger}`);
    77→              console.log(`Types: id=${typeof work.id}, name=${typeof name}, parentId=${typeof parentId}, fastTrigger=${typeof fastTrigger}`);
    78→              
    79→              db.stmt.insertWork.run(work.id, name, parentId, fastTrigger);
    80→              
    81→            } catch (error) {
    82→              console.error(`Error migrating work ${index + 1} (${work.id}):`, error);
    83→              console.error('Work object:', JSON.stringify(work, null, 2));
    84→              throw error;
    85→            }
    86→          });
    87→        }
    88→
    89→        // Migrate units
    90→        if (jsonData.units && Array.isArray(jsonData.units)) {
    91→          console.log(`Migrating ${jsonData.units.length} units...`);
    92→          jsonData.units.forEach((unit, index) => {
    93→            try {
    94→              if (!unit.id) unit.id = uuidv4();
    95→              
    96→              // Convert camelCase to snake_case and handle missing/undefined fields
    97→              const parentId = unit.parentId || unit.parent_id || null;
    98→              const unitType = unit.unitType || unit.unit_type || 'unknown';
    99→              const host = unit.host || 'unknown-host';
   100→              
   101→              // Handle hostname - could be string or array, convert to string
   102→              let hostname = null;
   103→              if (unit.hostname) {
   104→                if (Array.isArray(unit.hostname)) {
   105→                  hostname = unit.hostname[0]; // Take first hostname if array
   106→                } else {
   107→                  hostname = unit.hostname;
   108→                }
   109→              }
   110→              
   111→              const ip = unit.ip || null;
   112→              const args = unit.args ? JSON.stringify(unit.args) : '{}';
   113→              const automation = unit.automation !== false; // default true
   114→              const active = true; // new field, default true
   115→              
   116→              // Handle state - could be string or number
   117→              let state = -1;
   118→              if (unit.state !== undefined) {
   119→                if (typeof unit.state === 'string') {
   120→                  state = parseInt(unit.state) || (unit.state === 'true' ? 1 : 0);
   121→                } else {
   122→                  state = unit.state;
   123→                }
   124→              }
   125→
   126→              // Log the values we're about to insert for debugging
   127→              console.log(`Unit ${index + 1}/${jsonData.units.length}: ${unit.id} (${unitType})`);
   128→              
   129→              const values = [
   130→                unit.id,
   131→                parentId,
   132→                host,
   133→                hostname,
   134→                ip,
   135→                unitType,
   136→                automation ? 1 : 0,
   137→                active ? 1 : 0,
   138→                args,
   139→                state
   140→              ];
   141→              
   142→              // Check for any undefined values before inserting
   143→              values.forEach((val, i) => {
   144→                if (val === undefined) {
   145→                  console.error(`Parameter ${i} is undefined for unit ${unit.id}`);
   146→                  throw new Error(`Parameter ${i} is undefined`);
   147→                }
   148→              });
   149→
   150→              db.stmt.insertUnit.run(...values);
   151→              
   152→            } catch (error) {
   153→              if (error.message.includes('UNIQUE constraint failed')) {
   154→                console.warn(`Skipping duplicate unit: ${unit.host} (${unit.unitType || unit.unit_type})`);
