/*!
 * migration.js - Migrate from LowDB (db.json) to SQLite
 * Run this once to migrate existing data
 */

const fs = require('fs');
const path = require('path');
const SQLiteDB = require('./sqlite');
const { v4: uuidv4 } = require('uuid');

class DatabaseMigration {
  constructor(jsonPath = './db.json', sqlitePath = './data/mutech.db') {
    this.jsonPath = jsonPath;
    this.sqlitePath = sqlitePath;
  }

  async migrate() {
    console.log('Starting database migration from LowDB to SQLite...');

    // Read existing JSON data
    if (!fs.existsSync(this.jsonPath)) {
      console.log('No existing db.json found. Creating fresh SQLite database...');
      const db = new SQLiteDB(this.sqlitePath);
      db.close();
      return;
    }

    let jsonData;
    try {
      const jsonContent = fs.readFileSync(this.jsonPath, 'utf8');
      jsonData = JSON.parse(jsonContent);
      console.log('Successfully read existing db.json');
    } catch (error) {
      console.error('Error reading db.json:', error);
      throw error;
    }

    // Initialize SQLite database
    const db = new SQLiteDB(this.sqlitePath);

    try {
      // Backup existing SQLite if it exists
      if (fs.existsSync(this.sqlitePath)) {
        const backupPath = `${this.sqlitePath}.backup.${Date.now()}`;
        fs.copyFileSync(this.sqlitePath, backupPath);
        console.log(`Backed up existing SQLite to: ${backupPath}`);
      }

      // Migrate data in transaction
      const migrateTransaction = db.db.transaction(() => {
        // Migrate exhibits
        if (jsonData.exhibits && Array.isArray(jsonData.exhibits)) {
          console.log(`Migrating ${jsonData.exhibits.length} exhibits...`);
          jsonData.exhibits.forEach(exhibit => {
            if (!exhibit.id) exhibit.id = uuidv4();
            const name = exhibit.name || 'Unnamed Exhibit';
            db.stmt.insertExhibit.run(exhibit.id, name);
          });
        }

        // Migrate works
        if (jsonData.works && Array.isArray(jsonData.works)) {
          console.log(`Migrating ${jsonData.works.length} works...`);
          jsonData.works.forEach((work, index) => {
            try {
              if (!work.id) work.id = uuidv4();

              // Convert parentId to parent_id for consistency and ensure it's not undefined
              const parentId = work.parentId || work.parent_id || null;
              const name = work.name || 'Unnamed Work';
              const fastTrigger = 0; // fast_trigger defaults to 0 (false as integer)

              console.log(`Migrating work: ${name} (ID: ${work.id}, Parent ID: ${parentId})`);

              // Debug the exact values we're trying to insert
              console.log(`Values: id="${work.id}", name="${name}", parentId="${parentId}", fastTrigger=${fastTrigger}`);
              console.log(`Types: id=${typeof work.id}, name=${typeof name}, parentId=${typeof parentId}, fastTrigger=${typeof fastTrigger}`);

              db.stmt.insertWork.run(work.id, name, parentId, fastTrigger);

            } catch (error) {
              console.error(`Error migrating work ${index + 1} (${work.id}):`, error);
              console.error('Work object:', JSON.stringify(work, null, 2));
              throw error;
            }
          });
        }

        // Migrate units
        if (jsonData.units && Array.isArray(jsonData.units)) {
          console.log(`Migrating ${jsonData.units.length} units...`);
          jsonData.units.forEach((unit, index) => {
            try {
              if (!unit.id) unit.id = uuidv4();

              // Convert camelCase to snake_case and handle missing/undefined fields
              const parentId = unit.parentId || unit.parent_id || null;
              const unitType = unit.unitType || unit.unit_type || 'unknown';
              const host = unit.host || 'unknown-host';

              // Handle hostname - could be string or array, convert to string
              let hostname = null;
              if (unit.hostname) {
                if (Array.isArray(unit.hostname)) {
                  hostname = unit.hostname[0]; // Take first hostname if array
                } else {
                  hostname = unit.hostname;
                }
              }

              const ip = unit.ip || null;
              const args = unit.args ? JSON.stringify(unit.args) : '{}';
              const automation = unit.automation !== false; // default true
              const active = true; // new field, default true

              // Handle state - could be string or number
              let state = -1;
              if (unit.state !== undefined) {
                if (typeof unit.state === 'string') {
                  state = parseInt(unit.state) || (unit.state === 'true' ? 1 : 0);
                } else {
                  state = unit.state;
                }
              }

              // Log the values we're about to insert for debugging
              console.log(`Unit ${index + 1}/${jsonData.units.length}: ${unit.id} (${unitType})`);

              const values = [
                unit.id,
                parentId,
                host,
                hostname,
                ip,
                unitType,
                automation ? 1 : 0,
                active ? 1 : 0,
                args,
                state
              ];

              // Check for any undefined values before inserting
              values.forEach((val, i) => {
                if (val === undefined) {
                  console.error(`Parameter ${i} is undefined for unit ${unit.id}`);
                  throw new Error(`Parameter ${i} is undefined`);
                }
              });

              db.stmt.insertUnit.run(...values);

            } catch (error) {
              if (error.message.includes('UNIQUE constraint failed')) {
                console.warn(`Skipping duplicate unit: ${unit.host} (${unit.unitType || unit.unit_type})`);
              } else {
                console.error(`Error migrating unit ${index + 1} (${unit.id}):`, error);
                console.error('Unit object:', JSON.stringify(unit, null, 2));
                throw error;
              }
            }
          });
        }
      });

      migrateTransaction();

      // Verify migration
      const exhibits = db.stmt.getAllExhibits.all();
      const works = db.stmt.getAllWorks.all();
      const units = db.stmt.getAllUnits.all();

      console.log('\nMigration completed successfully!');
      console.log(`- Exhibits: ${exhibits.length}`);
      console.log(`- Works: ${works.length}`);
      console.log(`- Units: ${units.length}`);

      // Create backup of original JSON
      const jsonBackupPath = `${this.jsonPath}.backup.${Date.now()}`;
      fs.copyFileSync(this.jsonPath, jsonBackupPath);
      console.log(`\nOriginal db.json backed up to: ${jsonBackupPath}`);

    } catch (error) {
      console.error('Migration failed:', error);
      throw error;
    } finally {
      db.close();
    }
  }

  // Rollback migration (restore from JSON backup)
  async rollback(backupJsonPath) {
    console.log('Rolling back migration...');

    if (!fs.existsSync(backupJsonPath)) {
      throw new Error(`Backup file not found: ${backupJsonPath}`);
    }

    // Simply copy backup back to original location
    fs.copyFileSync(backupJsonPath, this.jsonPath);
    console.log(`Restored db.json from backup: ${backupJsonPath}`);
  }

  // Validate migration by comparing record counts
  async validate() {
    if (!fs.existsSync(this.jsonPath)) {
      console.log('No JSON file to validate against');
      return true;
    }

    const jsonData = JSON.parse(fs.readFileSync(this.jsonPath, 'utf8'));
    const db = new SQLiteDB(this.sqlitePath);

    try {
      const exhibits = db.stmt.getAllExhibits.all();
      const works = db.stmt.getAllWorks.all();
      const units = db.stmt.getAllUnits.all();

      const jsonExhibits = jsonData.exhibits || [];
      const jsonWorks = jsonData.works || [];
      const jsonUnits = jsonData.units || [];

      console.log('\nValidation Results:');
      console.log(`Exhibits: JSON=${jsonExhibits.length}, SQLite=${exhibits.length} ${jsonExhibits.length === exhibits.length ? '✓' : '✗'}`);
      console.log(`Works: JSON=${jsonWorks.length}, SQLite=${works.length} ${jsonWorks.length === works.length ? '✓' : '✗'}`);

      // Units might have fewer due to duplicate prevention
      const unitsValid = units.length >= jsonUnits.length - 10; // Allow some duplicates to be skipped
      console.log(`Units: JSON=${jsonUnits.length}, SQLite=${units.length} ${unitsValid ? '✓' : '✗'}`);

      const allValid = (jsonExhibits.length === exhibits.length) && 
                      (jsonWorks.length === works.length) && 
                      unitsValid;

      return allValid;

    } finally {
      db.close();
    }
  }
}

// CLI usage
if (require.main === module) {
  const migration = new DatabaseMigration();

  const command = process.argv[2];

  switch(command) {
    case 'migrate':
      migration.migrate()
        .then(() => console.log('Migration script completed successfully'))
        .catch(error => {
          console.error('Migration script failed:', error);
          process.exit(1);
        });
      break;

    case 'validate':
      migration.validate()
        .then(valid => {
          console.log(valid ? 'Validation passed' : 'Validation failed');
          process.exit(valid ? 0 : 1);
        })
        .catch(error => {
          console.error('Validation failed:', error);
          process.exit(1);
        });
      break;

    case 'rollback':
      const backupPath = process.argv[3];
      if (!backupPath) {
        console.error('Usage: node migration.js rollback <backup-json-path>');
        process.exit(1);
      }
      migration.rollback(backupPath)
        .then(() => console.log('Rollback completed'))
        .catch(error => {
          console.error('Rollback failed:', error);
          process.exit(1);
        });
      break;

    default:
      console.log('Usage:');
      console.log('  node migration.js migrate   - Migrate from JSON to SQLite');
      console.log('  node migration.js validate  - Validate migration');
      console.log('  node migration.js rollback <backup-path> - Rollback to JSON backup');
      break;
  }
}

module.exports = DatabaseMigration;

