/*!
 * app.js - Main Application Entry Point with Complete Queue and Timer System
 * Future-proof backend with SQLite, Fast Path, Queue, Timer, and Runner coordination
 */

process.env.DEBUG= 'mutech:*'; // Enable all debug logs

require("dotenv").config();
const debug = require('debug')('mutech:main');

const express = require("express");
const cors = require("cors");
const http = require("http");

// Core modules
const SocketManager = require("./src/core/socketManager");
const SQLiteDB = require("./src/database/sqlite");

// Managers
const FrontendManager = require("./src/managers/frontendManager");
const ApiManager = require("./src/managers/apiManager");

// Runners
const ConnectorCoordinator = require("./src/connectors/connectorCoordinator");

// Configuration
const config = {
    HTTP_PORT: process.env.HTTP_PORT || 8080,
    HTTP_URL: process.env.HTTP_URL || `http://localhost:${process.env.HTTP_PORT || 8080}`,
    CORS_ORIGIN: (process.env.CORS_ORIGIN || "http://localhost:3000,http://localhost:8080").split(','),
    DB_SYNC_INTERVAL: parseInt(process.env.DB_SYNC_INTERVAL) || 30000,
    FAST_PATH_ENABLED: process.env.FAST_PATH_ENABLED !== 'false',
    FAST_PATH_TIMEOUT: parseInt(process.env.FAST_PATH_TIMEOUT) || 1000,
    DATABASE_PATH: process.env.DATABASE_PATH || "./data/mutech.db",

    // Queue system configuration
    QUEUE_PROCESS_INTERVAL: process.env.QUEUE_PROCESS_INTERVAL || 500,
    QUEUE_MAX_OPERATIONS_PER_SECOND: process.env.QUEUE_MAX_OPERATIONS_PER_SECOND || 20,
    QUEUE_MAX_RETRIES: process.env.QUEUE_MAX_RETRIES || 3,
    QUEUE_RETRY_DELAY: process.env.QUEUE_RETRY_DELAY || 30000,

    // Per device type limits
    NETIO_MAX_OPS_PER_SECOND: process.env.NETIO_MAX_OPS_PER_SECOND || 3,
    PROJECTOR_MAX_OPS_PER_SECOND: process.env.PROJECTOR_MAX_OPS_PER_SECOND || 1,
    ANEL_MAX_OPS_PER_SECOND: process.env.ANEL_MAX_OPS_PER_SECOND || 5,
    SHELL_MAX_OPS_PER_SECOND: process.env.SHELL_MAX_OPS_PER_SECOND || 8,
    MAX_CONCURRENT_PER_DEVICE: process.env.MAX_CONCURRENT_PER_DEVICE || 3,

    // Timer system configuration
    PROJECTOR_INTERVAL: process.env.PROJECTOR_INTERVAL || 60000,
    NETIO_INTERVAL: process.env.NETIO_INTERVAL || 20000,
    ANEL_INTERVAL: process.env.ANEL_INTERVAL || 15000,
    SHELL_INTERVAL: process.env.SHELL_INTERVAL || 30000,
    UDP_INTERVAL: process.env.UDP_INTERVAL || 25000,
    TIMER_STARTUP_STAGGER: process.env.TIMER_STARTUP_STAGGER || 60000,
    TIMER_JITTER_PERCENT: process.env.TIMER_JITTER_PERCENT || 10,

    // Cooldown settings
    COOLDOWN_MULTIPLIER: process.env.COOLDOWN_MULTIPLIER || 1.5,
    MAX_COOLDOWN_INTERVAL: process.env.MAX_COOLDOWN_INTERVAL || 600000,
    MAX_FAILURE_COUNT: process.env.MAX_FAILURE_COUNT || 5
};

debug('Starting Mutech Device Control Backend with Complete Queue and Timer System...');
debug('Configuration:', {
    port: config.HTTP_PORT,
    database: config.DATABASE_PATH,
    fastPath: config.FAST_PATH_ENABLED,
    queueEnabled: true,
    timersEnabled: true,
    globalRateLimit: config.QUEUE_MAX_OPERATIONS_PER_SECOND + '/sec',
    dbSyncInterval: config.DB_SYNC_INTERVAL + 'ms',
    timerStagger: config.TIMER_STARTUP_STAGGER + 'ms'
});

// Initialize database
const db = new SQLiteDB(config.DATABASE_PATH);

// Initialize Express app
const app = express();
const server = http.createServer(app);

// CORS setup
const corsOptions = {
    origin: config.CORS_ORIGIN,
    methods: ["GET", "POST"],
    credentials: true
};

app.use(cors(corsOptions));
app.use(express.json());

// Initialize Socket.IO with CORS
const socketManager = new SocketManager(server, corsOptions, db, config);

// Initialize runner coordinator with queue and timer systems
const connectorCoordinator = new ConnectorCoordinator(socketManager.io, db, config);

// Initialize managers
const frontendManager = new FrontendManager(db, socketManager.io);
const apiManager = new ApiManager(db, connectorCoordinator, config);

// Connect frontend manager to runner coordinator
frontendManager.setconnectionCoordinator(connectorCoordinator);

// Setup Socket.IO event handlers
socketManager.setupFrontendHandlers(frontendManager);

// Setup API routes
app.use('/api', apiManager.getRouter());

// Queue management endpoints (for debugging and monitoring)
app.get('/api/queue/stats', (req, res) => {
    try {
        const stats = connectorCoordinator.getQueueStats();
        res.json(stats);
    } catch (error) {
        console.error('Error getting queue stats:', error);
        res.status(500).json({ error: 'Internal server error' });
    }
});

app.get('/api/queue/contents', (req, res) => {
    try {
        const contents = connectorCoordinator.getQueueContents();
        res.json(contents);
    } catch (error) {
        console.error('Error getting queue contents:', error);
        res.status(500).json({ error: 'Internal server error' });
    }
});

app.post('/api/queue/clear', (req, res) => {
    try {
        const clearedCount = connectorCoordinator.clearQueue();
        res.json({
            success: true,
            message: `Cleared ${clearedCount} operations from queue`,
            clearedCount: clearedCount
        });
    } catch (error) {
        console.error('Error clearing queue:', error);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// Timer management endpoints (for debugging and monitoring)
app.get('/api/timers/stats', (req, res) => {
    try {
        const stats = connectorCoordinator.getTimerStats();
        res.json(stats);
    } catch (error) {
        console.error('Error getting timer stats:', error);
        res.status(500).json({ error: 'Internal server error' });
    }
});

app.get('/api/timers/info', (req, res) => {
    try {
        const info = connectorCoordinator.getAllTimerInfo();
        res.json(info);
    } catch (error) {
        console.error('Error getting timer info:', error);
        res.status(500).json({ error: 'Internal server error' });
    }
});

app.post('/api/timers/start', (req, res) => {
    try {
        connectorCoordinator.startAutomaticStateChecks();
        res.json({
            success: true,
            message: 'Automatic state checks started'
        });
    } catch (error) {
        console.error('Error starting timers:', error);
        res.status(500).json({ error: 'Internal server error' });
    }
});

app.post('/api/timers/stop', (req, res) => {
    try {
        connectorCoordinator.stopAutomaticStateChecks();
        res.json({
            success: true,
            message: 'Automatic state checks stopped'
        });
    } catch (error) {
        console.error('Error stopping timers:', error);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// Debug endpoint to check for double timers
app.get('/api/debug/timers', (req, res) => {
    try {
        const allTimerInfo = connectorCoordinator.getAllTimerInfo();

        // Check for duplicates by unitId
        const unitCounts = {};
        const duplicates = [];

        allTimerInfo.forEach(timer => {
            if (unitCounts[timer.unitId]) {
                duplicates.push(timer.unitId);
            }
            unitCounts[timer.unitId] = (unitCounts[timer.unitId] || 0) + 1;
        });

        res.json({
            totalTimers: allTimerInfo.length,
            duplicateUnitIds: duplicates,
            duplicateCount: duplicates.length,
            timers: allTimerInfo.map(timer => ({
                displayName: timer.displayName,
                nextFireIn: Math.round(timer.nextFireIn / 1000) + 's',
                cooldownType: timer.cooldownType,
                unchangedCount: timer.unchangedStateCount,
                failureCount: timer.failureCount,
                lastState: timer.lastKnownState
            }))
        });
    } catch (error) {
        res.status(500).json({ error: error.message });
    }
});

// Debug endpoint to monitor cooldown effectiveness
app.get('/api/debug/cooldowns', (req, res) => {
    try {
        const timerStats = connectorCoordinator.getTimerStats();
        const allTimerInfo = connectorCoordinator.getAllTimerInfo();

        // Group by cooldown type
        const cooldownBreakdown = {
            normal: [],
            stateCooldown: [],
            failureCooldown: [],
            both: []
        };

        allTimerInfo.forEach(timer => {
            const hasStateCooldown = timer.unchangedStateCount > 0;
            const hasFailureCooldown = timer.failureCount > 0;

            if (hasStateCooldown && hasFailureCooldown) {
                cooldownBreakdown.both.push({
                    displayName: timer.displayName,
                    unchangedCount: timer.unchangedStateCount,
                    failureCount: timer.failureCount,
                    interval: Math.round(timer.interval / 1000) + 's'
                });
            } else if (hasStateCooldown) {
                cooldownBreakdown.stateCooldown.push({
                    displayName: timer.displayName,
                    unchangedCount: timer.unchangedStateCount,
                    interval: Math.round(timer.interval / 1000) + 's'
                });
            } else if (hasFailureCooldown) {
                cooldownBreakdown.failureCooldown.push({
                    displayName: timer.displayName,
                    failureCount: timer.failureCount,
                    interval: Math.round(timer.interval / 1000) + 's'
                });
            } else {
                cooldownBreakdown.normal.push({
                    displayName: timer.displayName,
                    interval: Math.round(timer.interval / 1000) + 's'
                });
            }
        });

        res.json({
            summary: {
                total: allTimerInfo.length,
                normal: cooldownBreakdown.normal.length,
                stateCooldown: cooldownBreakdown.stateCooldown.length,
                failureCooldown: cooldownBreakdown.failureCooldown.length,
                both: cooldownBreakdown.both.length
            },
            breakdown: cooldownBreakdown,
            stats: timerStats
        });
    } catch (error) {
        res.status(500).json({ error: error.message });
    }
});

// Debug endpoint to check queue contents
app.get('/api/debug/queue', (req, res) => {
    try {
        const queueContents = connectorCoordinator.getQueueContents();
        const queueStats = connectorCoordinator.getQueueStats();

        // Group by operation type
        const operationTypes = {};
        queueContents.forEach(item => {
            if (!operationTypes[item.type]) {
                operationTypes[item.type] = [];
            }
            operationTypes[item.type].push({
                displayName: item.displayName,
                attempts: item.attempts,
                waitingTime: Math.round(item.waitingTime / 1000) + 's',
                targetState: item.targetState
            });
        });

        res.json({
            queueLength: queueContents.length,
            operationTypes: operationTypes,
            stats: queueStats
        });
    } catch (error) {
        res.status(500).json({ error: error.message });
    }
});

// Debug function to simulate state changes for testing cooldown
app.post('/api/debug/simulate-state-change/:unitId', (req, res) => {
    try {
        const { unitId } = req.params;
        const { newState } = req.body;

        // Update unit state in database
        connectorCoordinator.db.updateUnitState(unitId, newState);

        // Trigger timer manager to handle the state change
        // This will reset cooldown if state actually changed
        connectorCoordinator.timerManager.onStateCheckComplete(unitId, true, { state: newState });

        res.json({
            success: true,
            message: `Simulated state change for unit ${unitId} to ${newState}`
        });
    } catch (error) {
        res.status(500).json({ error: error.message });
    }
});

// Runner information endpoint
app.get('/api/runners/info', (req, res) => {
    try {
        const info = connectorCoordinator.getRunnerInfo();
        res.json(info);
    } catch (error) {
        console.error('Error getting runner info:', error);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// Manual state check trigger endpoint
app.post('/api/state-checks/schedule', (req, res) => {
    try {
        const queueIds = connectorCoordinator.scheduleStateChecks();
        res.json({
            success: true,
            message: `Scheduled ${queueIds.length} state checks`,
            queueIds: queueIds.slice(0, 10) // Show first 10 IDs
        });
    } catch (error) {
        console.error('Error scheduling state checks:', error);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// Serve environment variables to frontend (compatibility)
app.get("/env.js", (req, res) => {
    const envVars = {
        SOCKETIO: config.HTTP_URL,
        ENVIRONMENT: process.env.NODE_ENV || "Development",
    };

    res.type("text/javascript");
    res.send(`window.__env__ = ${JSON.stringify(envVars)};`);
});

// Health check endpoint
app.get("/health", (req, res) => {
    const queueStats = connectorCoordinator.getQueueStats();
    const timerStats = connectorCoordinator.getTimerStats();

    res.json({
        status: "ok",
        database: "sqlite",
        fastPath: config.FAST_PATH_ENABLED,
        queue: {
            enabled: true,
            length: queueStats.queueLength,
            processed: queueStats.totalProcessed,
            rateLimit: config.QUEUE_MAX_OPERATIONS_PER_SECOND + '/sec',
            isProcessing: queueStats.isProcessing
        },
        timers: {
            enabled: true,
            active: timerStats.activeTimers,
            total: timerStats.totalTimers,
            stateChecksScheduled: timerStats.stateChecksScheduled,
            isStarted: timerStats.isStarted
        },
        timestamp: new Date().toISOString()
    });
});

// Start server
server.listen(config.HTTP_PORT, () => {
    debug(`Server listening on port ${config.HTTP_PORT}`);

    // Log database state
    try {
        const exhibits = db.getExhibits();
        const works = db.getWorks();
        const units = db.getUnits();
        debug(`Database loaded: ${exhibits.length} exhibits, ${works.length} works, ${units.length} units`);

        // Log systems status
        const queueStats = connectorCoordinator.getQueueStats();
        debug(`Queue System: ${queueStats.config.maxOperationsPerSecond}/sec global limit, ${queueStats.config.processInterval}ms interval`);

        // Start automatic state checks after a short delay to let everything initialize
        setTimeout(() => {
            debug('Starting automatic timer-based state checks...');
            connectorCoordinator.startAutomaticStateChecks();

            const timerStats = connectorCoordinator.getTimerStats();
            debug(`Timer System: ${timerStats.totalTimers} timers initialized, staggered startup over ${config.TIMER_STARTUP_STAGGER}ms`);
        }, 3000); // 3 second delay for initialization

    } catch (error) {
        console.error("Database error:", error);
    }

    // Start periodic database sync
    socketManager.startPeriodicSync();
});

// Graceful shutdown
function gracefulShutdown(signal) {
    debug(`Received ${signal}. Starting graceful shutdown...`);

    // Shutdown runner coordinator (includes queue and timers)
    connectorCoordinator.shutdown();

    server.close(() => {
        debug('HTTP server closed');

        try {
            db.close();
            debug('Database connection closed');
        } catch (error) {
            console.error('Error closing database:', error);
        }

        process.exit(0);
    });

    // Force exit after 10 seconds
    setTimeout(() => {
        console.error('Forced shutdown');
        process.exit(1);
    }, 10000);
}

// Handle shutdown signals
process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));
process.on('SIGHUP', () => gracefulShutdown('SIGHUP'));

// Log uncaught exceptions but continue running
process.on("uncaughtException", (err) => {
    console.error("Uncaught exception (continuing):", err);
});

process.on("unhandledRejection", (reason, promise) => {
    console.error("Unhandled rejection (continuing):", reason);
});

