/*!
 * apiManager.js - Streamlined REST API Manager with Fast Path
 */

const express = require('express');

class ApiManager {
  constructor(db, runnerCoordinator, config) {
    this.db = db;
    this.runnerCoordinator = runnerCoordinator;
    this.config = config;
    this.router = express.Router();

    this.setupRoutes();

    console.log('API Manager initialized with Fast Path:', config.FAST_PATH_ENABLED);
  }

  setupRoutes() {
    // Health check
    this.router.get('/', (req, res) => {
      res.json({ 
        status: 'ok', 
        service: 'mutech-device-control-api',
        fastPath: this.config.FAST_PATH_ENABLED
      });
    });

    // Get all exhibits
    this.router.get('/exhibit/', (req, res) => {
      try {
        const exhibits = this.db.getExhibits();
        res.json(exhibits);
      } catch (error) {
        console.error('Error getting exhibits:', error);
        res.status(500).json({ error: 'Internal server error' });
      }
    });

    // Get exhibit by ID with automation units
    this.router.get('/exhibit/:id', (req, res) => {
      try {
        const works = this.db.getWorksByExhibit(req.params.id);
        if (works.length === 0) {
          return res.status(404).json({ error: 'Exhibit not found or no works' });
        }

        const units = [];
        works.forEach((work) => {
          const workUnits = this.db.getUnitsByWork(work.id).filter(u => u.automation);
          units.push(...workUnits);
        });

        res.json(units);
      } catch (error) {
        console.error('Error getting exhibit units:', error);
        res.status(500).json({ error: 'Internal server error' });
      }
    });

    // Control exhibit (GET and POST)
    this.router.get('/exhibit/:id/:state', (req, res) => {
      this.handleExhibitControl(req, res);
    });

    this.router.post('/exhibit/:id/:state', (req, res) => {
      this.handleExhibitControl(req, res);
    });

    // Get all works
    this.router.get('/work/', (req, res) => {
      try {
        const works = this.db.getWorks();
        res.json(works);
      } catch (error) {
        console.error('Error getting works:', error);
        res.status(500).json({ error: 'Internal server error' });
      }
    });

    // Get work by ID with units
    this.router.get('/work/:id', (req, res) => {
      try {
        const work = this.db.getWorkById(req.params.id);
        if (!work) {
          return res.status(404).json({ error: 'Work not found' });
        }

        const units = this.db.getUnitsByWork(work.id);
        res.json(units);
      } catch (error) {
        console.error('Error getting work units:', error);
        res.status(500).json({ error: 'Internal server error' });
      }
    });

    // Control work (GET and POST) - FAST PATH ENABLED
    this.router.get('/work/:id/:state', (req, res) => {
      this.handleWorkControl(req, res);
    });

    this.router.post('/work/:id/:state', (req, res) => {
      this.handleWorkControl(req, res);
    });
  }

  async handleExhibitControl(req, res) {
    const startTime = Date.now();

    try {
      const state = this.parseState(req.params.state);
      const controlData = { 
        type: "exhibit", 
        id: req.params.id 
      };

      console.log(`Exhibit control: ${req.params.id} -> ${state ? 'ON' : 'OFF'}`);

      // Forward to runner coordinator (normal path for exhibits)
      await this.runnerCoordinator.executeQueued(controlData, state);

      const responseTime = Date.now() - startTime;
      res.json({ 
        status: 'queued', 
        fast: false,
        responseTime: `${responseTime}ms`,
        message: `Exhibit ${state ? 'activated' : 'deactivated'}`
      });

    } catch (error) {
      console.error('Error controlling exhibit:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  }

  async handleWorkControl(req, res) {
    const startTime = Date.now();

    try {
      const work = this.db.getWorkById(req.params.id);
      if (!work) {
