/*!
 * socketManager.js - Socket.IO Coordination and Namespace Management
 */

const { Server } = require("socket.io");

class SocketManager {
  constructor(server, corsOptions, db, config) {
    this.db = db;
    this.config = config;
    this.connectedClients = [];
    this.syncInterval = null;

    // Initialize Socket.IO with CORS
    this.io = new Server(server, {
      cors: corsOptions
    });

    this.setupNamespaces();
    this.setupMainConnection();

    console.log('Socket.IO Manager initialized');
  }

  setupNamespaces() {
    // Future runner namespaces (empty shells for now)
    this.setupRunnerNamespace('/runner-shell', 'Shell Runner');
    this.setupRunnerNamespace('/runner-netio', 'NETIO Runner');
    this.setupRunnerNamespace('/runner-pjlink', 'PJLink Runner');
    this.setupRunnerNamespace('/runner-anel', 'ANEL Runner');
    this.setupDebugNamespace();
  }

  setupRunnerNamespace(namespace, name) {
    this.io.of(namespace).on('connection', (socket) => {
      console.log(`${name} connected:`, socket.id);

      // Future: Runner-specific event handlers will go here
      socket.on('disconnect', () => {
        console.log(`${name} disconnected:`, socket.id);
      });
    });
  }

  setupDebugNamespace() {
    this.io.of('/debug').on('connection', (socket) => {
      console.log('Debug client connected:', socket.id);

      // Future: Debug event handlers will go here
      socket.on('disconnect', () => {
        console.log('Debug client disconnected:', socket.id);
      });
    });
  }

  setupMainConnection() {
    // Main namespace for frontend clients
    this.io.on('connection', (socket) => {
      this.connectedClients.push(socket);
      console.log(`Frontend client connected: ${socket.id} (total: ${this.connectedClients.length})`);

      // Immediately send current database state
      this.emitDatabaseState();

      socket.on('disconnect', () => {
        const index = this.connectedClients.indexOf(socket);
        if (index > -1) {
          this.connectedClients.splice(index, 1);
        }
        console.log(`Frontend client disconnected: ${socket.id} (total: ${this.connectedClients.length})`);
      });
    });
  }

  setupFrontendHandlers(frontendManager) {
    this.io.on('connection', (socket) => {
      // Frontend compatibility events (from original backend)
      socket.on('command', (request, callback) => {
        frontendManager.handleCommand(request, callback);
      });

      socket.on('updateUnits', (request, callback) => {
        frontendManager.handleUpdateUnits(request, callback);
      });

      socket.on('testShellCommand', (data, callback) => {
        frontendManager.handleTestShellCommand(data, callback);
      });

      socket.on('changeState', (data, callback) => {
        frontendManager.handleChangeState(data, callback);
      });
    });
  }

  emitDatabaseState() {
    try {
      const exhibits = this.db.getExhibits();
      const works = this.db.getWorks();
      const units = this.db.getUnits();

      const databaseState = {
        exhibits: exhibits,
        works: works,
        units: units
      };

      // Add 1 second delay like original backend
      setTimeout(() => {
        this.io.emit("database", databaseState);
        console.log(`Database state emitted: ${exhibits.length} exhibits, ${works.length} works, ${units.length} units`);
      }, 1000);

    } catch (error) {
      console.error('Error emitting database state:', error);
    }
  }

  startPeriodicSync() {
    if (this.syncInterval) {
      clearInterval(this.syncInterval);
    }

    console.log(`Starting periodic database sync every ${this.config.DB_SYNC_INTERVAL}ms`);

    this.syncInterval = setInterval(() => {
      console.log('Periodic database sync...');
      this.emitDatabaseState();
    }, this.config.DB_SYNC_INTERVAL);
  }

  stopPeriodicSync() {
    if (this.syncInterval) {
      clearInterval(this.syncInterval);
      this.syncInterval = null;
      console.log('Periodic database sync stopped');
    }
  }

  // Future: Selective update methods (implement but don't activate)
  emitUnitChanged(unit) {
    // For future frontend: selective updates
    this.io.emit('unitChanged', { unit: unit });
  }

  emitWorkChanged(work) {
    // For future frontend: selective updates  
    this.io.emit('workChanged', { work: work });
  }

