/*!
 * projectorConnector.js - PJLink Socket.IO Client Connector
 * Connects to pjlink-runner microservice via Socket.IO
 */

const debug = require('debug')('mutech:projector-connector');

class ProjectorConnector {
  constructor(io, db) {
    this.io = io;
    this.db = db;
    this.type = 'projector';

    // Connection state
    this.isRunnerConnected = false;
    this.runnerSocket = null;

    // Configuration - projectors are slower than other devices
    this.requestTimeout = 15000; // 15 seconds for slow projectors

    this.setupProjectorNamespace();

    debug('Projector Connector initialized, waiting for runner connection');
  }

  setupProjectorNamespace() {
    // Setup namespace for pjlink-runner to connect to
    this.projectorNamespace = this.io.of('/runner-pjlink');

    this.projectorNamespace.on('connection', (socket) => {
      this.isRunnerConnected = true;
      this.runnerSocket = socket;
      debug('PJLink runner connected: %s', socket.id);

      // Emit debug event
      this.emitDebugEvent('runner_connected', {
        runnerId: socket.id,
        timestamp: Date.now()
      });

      socket.on('disconnect', () => {
        this.isRunnerConnected = false;
        this.runnerSocket = null;
        debug('PJLink runner disconnected: %s', socket.id);

        // Emit debug event
        this.emitDebugEvent('runner_disconnected', {
          runnerId: socket.id,
          timestamp: Date.now()
        });
      });
    });
  }

  async getState(unit) {
    const startTime = Date.now();

    try {
      debug('Getting state for unit: %s (%s)', unit.id, this.getHostForUnit(unit));

      // Check if runner is connected
      if (!this.isRunnerConnected || !this.runnerSocket) {
        const error = 'PJLink runner not connected';
        debug('getState failed: %s', error);
        return {
          success: false,
          state: -1,
          error: error,
          unitType: this.type
        };
      }

      // Build request
      const request = {
        unitId: unit.id,
        operation: 'getState',
        ip: this.getHostForUnit(unit),
        password: unit.args?.password || '',
        timeout: 10000 // 10 seconds for state queries
      };

      // Send request with timeout
      const response = await this.sendRequestWithTimeout('executeCommand', request);

      if (response.success) {
        debug('getState success for unit: %s, state: %d (%s)', unit.id, response.state, this.getStateDescription(response.state));

        return {
          success: true,
          state: response.state,
          unitType: this.type,
          host: request.ip,
          stateDescription: this.getStateDescription(response.state),
          lampHours: response.lampHours,
          temperature: response.temperature,
          timestamp: Date.now()
        };
      } else {
        debug('getState failed for unit: %s, error: %s', unit.id, response.error);
        return {
